function highlight(raw, term) { if (!term) return esc(raw); const re = new RegExp(term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi'); let out = '', last = 0, m; while ((m = re.exec(raw))) { out += esc(raw.slice(last, m.index)) + '<mark>' + esc(m[0]) + '</mark>'; last = m.index + m[0].length; if (!m[0].length) re.lastIndex++; } return out + esc(raw.slice(last)); }
