function setView(v) { evView = v; document.querySelectorAll('[data-view]').forEach(b => b.classList.toggle('active', b.dataset.view === v)); $('evidenceImage').hidden = v !== 'image'; $('evidenceText').hidden = v !== 'text'; if (v === 'image') { const p = evPaper(); if (p) renderImage(p, +$('evidencePage').value || 1); } }
