function source() { const p = evPaper(); return { name: $('verifiedName').value.trim() || paperLabel(p), year: p?.year || '', sourcePaper: p ? p.filename + (p.doi ? ' · doi:' + p.doi : '') : '', sourcePage: $('verifiedPage').value, sourceExcerpt: $('verifiedExcerpt').value.trim(), verified: false }; }
function ensureMetric(allowed, def) { if (allowed.includes(M())) return true; if (project.rows.some(r => r.include)) { toast(`Proyek memakai ${M()}. Jangan mencampur effect measure — Backup JSON, lalu buat proyek baru untuk outcome ini.`); return false; } project.metric = def; syncControls(); return true; }
