/* ---------- calculator ---------- */
const CALCS = [
  { id: 'mediqr', title: 'Median + IQR → Mean & SD', ref: 'Luo et al. 2018 (mean); Wan et al. 2014 (SD). Asumsi distribusi mendekati normal.', f: [['q1', 'Q1'], ['med', 'Median'], ['q3', 'Q3'], ['n', 'n']], run: v => { const r = S.conv.medianIQR(v.q1, v.med, v.q3, v.n); return { out: [['Mean', r.mean], ['SD', r.sd]], arm: { mean: r.mean, sd: r.sd, n: v.n } }; } },
  { id: 'medrange', title: 'Median + min–max → Mean & SD', ref: 'Luo et al. 2018; Wan et al. 2014.', f: [['a', 'Minimum'], ['med', 'Median'], ['b', 'Maksimum'], ['n', 'n']], run: v => { const r = S.conv.medianRange(v.a, v.med, v.b, v.n); return { out: [['Mean', r.mean], ['SD', r.sd]], arm: { mean: r.mean, sd: r.sd, n: v.n } }; } },
  { id: 'se2sd', title: 'SE of mean → SD', ref: 'Cochrane Handbook 6.5.2.2: SD = SE × √n.', f: [['mean', 'Mean'], ['se', 'SE'], ['n', 'n']], run: v => { const sd = S.conv.seToSd(v.se, v.n); return { out: [['SD', sd]], arm: { mean: v.mean, sd, n: v.n } }; } },
  { id: 'ci2sd', title: 'CI of mean → SD', ref: 'Cochrane 6.5.2.2: t-distribution bila n < 60.', f: [['mean', 'Mean'], ['lo', 'Lower 95%'], ['hi', 'Upper 95%'], ['n', 'n']], run: v => { const sd = S.conv.ciToSd(v.lo, v.hi, v.n); return { out: [['SD', sd]], arm: { mean: v.mean, sd, n: v.n } }; } },
  { id: 'combine', title: 'Gabungkan 2 arm (multi-arm)', ref: 'Cochrane Table 6.5.a — hindari unit-of-analysis error.', f: [['n1', 'n₁'], ['m1', 'Mean₁'], ['s1', 'SD₁'], ['n2', 'n₂'], ['m2', 'Mean₂'], ['s2', 'SD₂']], run: v => { const r = S.conv.combineArms(v.n1, v.m1, v.s1, v.n2, v.m2, v.s2); return { out: [['N', r.n], ['Mean', r.mean], ['SD', r.sd]], arm: { mean: r.mean, sd: r.sd, n: r.n } }; } },
  { id: 'ratio', title: 'Rasio + 95% CI → ln & SE', ref: 'SE = (ln U − ln L) / (2 × 1.96).', f: [['est', 'Estimate'], ['lo', 'Lower'], ['hi', 'Upper']], run: v => { const r = S.conv.ratioCI(v.est, v.lo, v.hi); return { out: [['yi = ln(est)', r.yi], ['SE', r.se], ['vi', r.vi], ['p (Wald)', r.p]], ratio: v }; } },
  { id: 'p2se', title: 'Estimate + p-value → SE', ref: 'SE = |estimate| / z(1 − p/2); estimate pada skala analisis (mis. ln HR).', f: [['est', 'Estimate (skala analisis)'], ['p', 'p (dua sisi)']], run: v => [['SE', S.conv.pToSe(v.est, v.p)], ['z', S.qnorm(1 - v.p / 2)]] },
  { id: 'or2smd', title: 'ln(OR) ↔ SMD', ref: 'Chinn 2000: d = ln(OR) × √3/π.', f: [['lnor', 'ln(OR)'], ['se', 'SE ln(OR)']], run: v => { const r = S.conv.orToSmd(v.lnor, v.se * v.se); return [['SMD (d)', r.d], ['SE(d)', Math.sqrt(r.v)]]; } },
  { id: 'r2z', title: 'r → Fisher z', ref: 'z = atanh(r); SE = 1/√(n − 3).', f: [['r', 'r'], ['n', 'n']], run: v => [['z', Math.atanh(v.r)], ['SE', 1 / Math.sqrt(v.n - 3)]] }];
const calcRes = {};
function buildCalculator() { $('calcGrid').innerHTML = CALCS.map(c => `<article class="panel calc-card" id="calc-${c.id}"><h3>${esc(c.title)}</h3><span class="ref">${esc(c.ref)}</span><div class="mini-fields${c.f.length > 4 ? ' six' : ''}">${c.f.map(([k, l]) => `<label>${esc(l)}<input id="calc-${c.id}-${k}" data-calc="${c.id}" type="number" step="any"></label>`).join('')}</div><div class="calc-out" id="calc-${c.id}-out"><div><small>Hasil</small><b>—</b></div></div><div class="head-actions" id="calc-${c.id}-act"></div></article>`).join(''); }
function runCalc(id) { const c = CALCS.find(x => x.id === id), v = {}; for (const [k] of c.f) { v[k] = S.num($(`calc-${id}-${k}`).value); if (!Number.isFinite(v[k])) { $(`calc-${id}-out`).innerHTML = '<div><small>Hasil</small><b>—</b></div>'; $(`calc-${id}-act`).innerHTML = ''; return; } }
  let r; try { r = c.run(v); } catch (e) { r = []; } const out = Array.isArray(r) ? r : r.out; calcRes[id] = r; $(`calc-${id}-out`).innerHTML = out.map(([k, x]) => `<div><small>${esc(k)}</small><b>${Number.isFinite(x) ? +x.toFixed(5) : '—'}</b></div>`).join('');
  $(`calc-${id}-act`).innerHTML = r.arm ? `<button class="mini-act" data-arm="T" data-c="${id}">→ Isi arm Intervensi</button><button class="mini-act" data-arm="C" data-c="${id}">→ Isi arm Kontrol</button>` : r.ratio ? `<button class="mini-act" data-toratio="${id}">→ Isi form rasio</button>` : ''; }

/* ---------- PRISMA & simulation ---------- */
function prismaVals() { const p = project.prisma, screened = p.identified - p.duplicates, sought = screened - p.screenExcluded, assessed = sought - p.notRetrieved, included = assessed - p.fullExcluded; return { p, screened, sought, assessed, included, bad: [screened, sought, assessed, included].some(x => x < 0) }; }
function renderPrisma() { const v = prismaVals(), w = []; if (v.bad) w.push('Alur tidak konsisten: ada tahap bernilai negatif.'); else if (v.included !== project.rows.filter(r => r.include).length) w.push('Jumlah studi di PRISMA berbeda dari studi Include (bisa wajar bila satu studi punya beberapa laporan).');
  $('prismaWarnings').textContent = w.join(' ') || 'Angka konsisten secara aritmetika.';
  const steps = [['Records identified', v.p.identified], ['Records screened (after duplicates removed)', v.screened], ['Reports sought for retrieval', v.sought], ['Reports assessed for eligibility', v.assessed], ['Studies included in review', v.included]], side = [`Duplicates removed: ${v.p.duplicates}`, `Records excluded: ${v.p.screenExcluded}`, `Reports not retrieved: ${v.p.notRetrieved}`, `Reports excluded: ${v.p.fullExcluded}`];
  $('prismaChart').innerHTML = steps.map((s, i) => `<div class="prisma-step ${i === steps.length - 1 ? 'end' : ''}">${esc(s[0])}<b>${v.bad ? 'Periksa' : s[1]}</b></div>${i < side.length ? `<span class="prisma-arrow">↓ <small>${esc(side[i])}</small></span>` : ''}`).join(''); }
function exportPrisma() { const v = prismaVals(); if (v.bad) return toast('Perbaiki angka PRISMA.'); const main = [['Records identified', v.p.identified], ['Records screened', v.screened], ['Reports sought for retrieval', v.sought], ['Reports assessed for eligibility', v.assessed], ['Studies included in review', v.included]], side = [['Duplicates removed', v.p.duplicates], ['Records excluded', v.p.screenExcluded], ['Reports not retrieved', v.p.notRetrieved], ['Reports excluded', v.p.fullExcluded]];
  let s = `<svg xmlns="http://www.w3.org/2000/svg" width="820" height="640" viewBox="0 0 820 640" font-family="Helvetica,Arial,sans-serif"><rect width="820" height="640" fill="#fff"/><text x="410" y="34" font-size="20" font-weight="bold" fill="#33433c" text-anchor="middle">PRISMA 2020 flow diagram</text>`;
  main.forEach(([t, n], i) => { const y = 60 + i * 112; s += `<rect x="60" y="${y}" width="380" height="70" rx="10" fill="${i === 4 ? '#dff0e6' : '#fff'}" stroke="#7fa08e"/><text x="250" y="${y + 30}" font-size="14" fill="#33433c" text-anchor="middle">${t}</text><text x="250" y="${y + 54}" font-size="18" font-weight="bold" fill="#33433c" text-anchor="middle">(n = ${n})</text>`; if (i < 4) { s += `<line x1="250" y1="${y + 70}" x2="250" y2="${y + 108}" stroke="#7fa08e" stroke-width="2"/><path d="M244 ${y + 101}L250 ${y + 110}L256 ${y + 101}" fill="#7fa08e"/><line x1="250" y1="${y + 90}" x2="500" y2="${y + 90}" stroke="#7fa08e" stroke-width="1.5"/><rect x="500" y="${y + 66}" width="280" height="48" rx="8" fill="#f7f4ef" stroke="#c9b9a8"/><text x="640" y="${y + 87}" font-size="13" fill="#5a4b40" text-anchor="middle">${side[i][0]}</text><text x="640" y="${y + 105}" font-size="13" font-weight="bold" fill="#5a4b40" text-anchor="middle">(n = ${side[i][1]})</text>`; } });
  download('prisma-2020-flow.svg', s + '</svg>', 'image/svg+xml;charset=utf-8'); }
function simulate() { const [a, n1, c, n0] = ['simA', 'simN1', 'simC', 'simN0'].map(id => S.num($(id).value)); if (![a, n1, c, n0].every(x => Number.isSafeInteger(x) && x >= 0) || n1 < 1 || n0 < 1 || a > n1 || c > n0) { $('simStats').innerHTML = '<div class="notice amber">Input tidak valid: 0 ≤ events ≤ total.</div>'; $('simBars').innerHTML = ''; simResult = null; return; }
  const r1 = a / n1, r0 = c / n0, arr = r0 - r1, cell = { a, b: n1 - a, c, d: n0 - c }, rr = S.effect(cell, 'RR'), or = S.effect(cell, 'OR'), z = 1.96, ci = e => e.ok ? `[${fmt(Math.exp(e.y - z * Math.sqrt(e.v)), 2)}, ${fmt(Math.exp(e.y + z * Math.sqrt(e.v)), 2)}]` : '';
  simResult = { r1, r0, rr: rr.ok ? Math.exp(rr.y) : NaN, or: or.ok ? Math.exp(or.y) : NaN };
  const tiles = [['Risk intervensi', fmt(r1 * 100, 1) + '%'], ['Risk kontrol', fmt(r0 * 100, 1) + '%'], ['Risk Ratio', fmt(simResult.rr, 3) + ' ' + ci(rr)], ['Odds Ratio', fmt(simResult.or, 3) + ' ' + ci(or)], ['ARR (kontrol − intervensi)', fmt(arr * 100, 2) + ' pp'], [arr > 0 ? 'NNT' : arr < 0 ? 'NNH' : 'NNT/NNH', arr ? Math.ceil(1 / Math.abs(arr)) : 'tak terdefinisi']];
  $('simStats').innerHTML = tiles.map(([k, v]) => `<div class="sim-tile"><small>${esc(k)}</small><b>${esc(v)}</b></div>`).join('') + `<p class="smallprint" style="grid-column:1/-1">${rr.corrected ? 'Koreksi 0.5 dipakai (zero cell). ' : ''}Asumsi: event = outcome merugikan.</p>`;
  let s = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 570 190" role="img" aria-label="Risk per kelompok">`; [['Intervensi', r1, '#78ac98'], ['Kontrol', r0, '#e6a087']].forEach(([l, v, col], i) => { const y = 40 + i * 74; s += `<text x="15" y="${y + 17}" font-size="13" fill="#576f62">${l}</text><rect x="120" y="${y}" width="360" height="24" rx="12" fill="#e9f0ea"/><rect x="120" y="${y}" width="${360 * v}" height="24" rx="12" fill="${col}"/><text x="${128 + 360 * v}" y="${y + 17}" font-size="13" fill="#456957">${fmt(v * 100, 1)}%</text>`; }); $('simBars').innerHTML = s + '</svg>'; }

/* ---------- backend ---------- */
async function checkBackend() { try { const r = await fetch(backendBase() + '/api/health', { signal: AbortSignal.timeout(5000) }); if (!r.ok) throw Error('HTTP ' + r.status); const d = await r.json(); $('backendStatus').textContent = `✓ Engine ${d.version || ''} siap · OCR ${d.ocr ? 'tersedia' : 'tidak ada'} · R ${d.R ? (d.metafor ? '+ metafor ✓' : 'tanpa metafor') : 'tidak terpasang'} · PyMuPDF tables ${d.tables ? '✓' : '—'}`; } catch (e) { $('backendStatus').textContent = 'Backend belum terjangkau: ' + e.message + '. Aplikasi tetap berfungsi di browser.'; } }
async function runBackend(files) { for (const file of [...files]) { try { const base = backendBase(); if (!isLocal(base) && !confirm('PDF akan DIKIRIM ke ' + base + '. Lanjutkan hanya untuk server milik Anda.')) return; const fd = new FormData(); fd.append('file', file); fd.append('ocr', String($('ocrToggle').checked)); fd.append('lang', $('ocrLang').value.replace('+', '+'));
    $('backendStatus').textContent = 'Python memproses ' + file.name + '…'; const r = await fetch(base + '/api/extract', { method: 'POST', body: fd }); if (!r.ok) throw Error((await r.text()).slice(0, 240)); const d = await r.json();
    const pages = (d.pages || []).map(x => ({ page: x.page, text: E.normalize(x.text || ''), engine: x.engine || 'PyMuPDF' })), full = pages.map(x => x.text).join('\n\n'), desc = E.describe(full, pages, { info: { Title: d.metadata?.title } });
    const p = addPaper(makePaper(desc, { filename: file.name, numPages: d.page_count || pages.length, pageData: pages, tables: (d.tables || []).map((t, i) => ({ page: t.page, index: t.index || i + 1, method: t.method || 'PyMuPDF find_tables', rows: t.rows || [] })), engine: 'Python ' + (d.engine || 'PyMuPDF'), ocrPages: d.ocr_pages || [], twoColumnPages: 0 }));
    $('backendStatus').textContent = `✓ ${file.name}: ${pages.length} halaman, ${(d.tables || []).length} tabel, ${(d.ocr_pages || []).length} halaman OCR.`; showPage('evidence'); $('evidencePaper').value = p.id; populatePages(); } catch (e) { $('backendStatus').textContent = 'Ekstraksi Python gagal: ' + e.message; } } }

/* ---------- navigation ---------- */
function showPage(pg) { page = TITLES[pg] ? pg : 'dashboard'; document.querySelectorAll('.page').forEach(e => e.classList.toggle('active', e.id === 'page-' + page)); document.querySelectorAll('.nav-link').forEach(e => e.classList.toggle('active', e.dataset.page === page)); $('pageTitle').textContent = TITLES[page]; $('breadcrumb').textContent = TITLES[page].toUpperCase(); window.scrollTo({ top: 0, behavior: 'smooth' });
  if (page === 'evidence') populateEvidence(); if (page === 'simulation') simulate(); renderCurrent(); if (location.hash !== '#' + page) history.replaceState(null, '', '#' + page); }

/* ---------- wiring ---------- */
