  on('helpBtn', 'click', () => { $('helpModalBody').innerHTML = window.UPHelp.guideHtml(page); $('helpModal').showModal(); }); on('closeHelp', 'click', () => $('helpModal').close()); on('helpModal', 'click', e => { if (e.target === $('helpModal')) $('helpModal').close(); }); on('helpModalAll', 'click', () => { $('helpModal').close(); showPage('help'); });
  on('glossarySearch', 'input', renderHelp); on('page-help', 'click', e => { const b = e.target.closest('[data-go-help]'); if (b) showPage(b.dataset.goHelp); });
  window.addEventListener('up-open-glossary', e => openGlossary(e.detail));
  document.addEventListener('click', async e => { const b = e.target.closest('[data-copy-conclusion]'); if (!b || !A.insight) return; try { await navigator.clipboard.writeText(b.dataset.copyConclusion === 'en' ? A.insight.en : A.insight.conclusionText); toast('Kesimpulan disalin.'); } catch (er) { toast('Clipboard tidak tersedia.'); } });
  const demo = () => { loadDemo(); showPage('analysis'); }; on('heroDemo', 'click', demo); on('sidebarDemo', 'click', demo); on('loadDemo', 'click', loadDemo);
