  on('dropzone', 'keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); $('pdfInput').click(); } }); on('dropzone', 'dragover', e => { e.preventDefault(); $('dropzone').classList.add('dragover'); }); on('dropzone', 'dragleave', () => $('dropzone').classList.remove('dragover')); on('dropzone', 'drop', e => { e.preventDefault(); $('dropzone').classList.remove('dragover'); handleFiles(e.dataTransfer.files); });
