  on('papersList', 'click', e => { const b = e.target.closest('[data-paper]'); if (b) { activePaper = b.dataset.paper; renderPaperList(); } });
  on('removePaper', 'click', () => { if (!activePaper || !confirm('Hapus paper ini dari proyek?')) return; project.papers = project.papers.filter(p => p.id !== activePaper); pdfDocs.delete(activePaper); activePaper = null; renderPaperList(); refresh(); });
  on('crossrefBtn', 'click', () => { const p = project.papers.find(x => x.id === activePaper); if (p) enrichCrossref(p, false); });
