  on('evidenceTables', 'click', e => { const c = e.target.closest('[data-csv]'); if (c) { const p = evPaper(), t = p.tables[+c.dataset.csv]; download(`table-p${t.page}-${t.index}.csv`, '\ufeff' + E.tableToCsv(t), 'text/csv;charset=utf-8'); } else jump(e); });
  on('exportStatsCsv', 'click', () => { const p = evPaper(); if (!p) return toast('Pilih paper.'); download('statistik-' + p.filename.replace(/\W+/g, '-') + '.csv', '\ufeff' + ['paper,page,type,value,confidence,excerpt', ...p.stats.map(s => [p.filename, s.page, s.type, statValue(s), s.confidence, s.excerpt].map(csvCell).join(','))].join('\r\n'), 'text/csv;charset=utf-8'); });
  on('exportEvidenceCsv', 'click', () => { const p = evPaper(); if (!p) return toast('Pilih paper.'); download('kandidat-angka.csv', '\ufeff' + ['paper,page,value,excerpt', ...candidates(p).map(c => [p.filename, c.page, c.value, c.excerpt].map(csvCell).join(','))].join('\r\n'), 'text/csv;charset=utf-8'); });
  on('downloadEvidenceJson', 'click', () => { const p = evPaper(); if (p) download('extraction-' + p.filename.replace(/\W+/g, '-') + '.json', JSON.stringify(p, null, 2), 'application/json'); });
